chunks = [
    {"id": "c1", "text": "Falcon plan costs twenty dollars.", "allowed_roles": ["public", "admin"]},
    {"id": "c2", "text": "Internal cost breakdown for Falcon plan.", "allowed_roles": ["admin"]},
    {"id": "c3", "text": "Uncategorized chunk with no tag."},
]

def is_permitted(chunk, user_role):
    # deny by default: an untagged chunk is treated as inaccessible
    allowed = chunk.get("allowed_roles")
    if allowed is None:
        return False
    return user_role in allowed

def filter_then_rank(chunks, user_role, top_k=2):
    # filter before ranking, not after
    permitted = [c for c in chunks if is_permitted(c, user_role)]
    return permitted[:top_k]

response_cache = {"admin": "Cached admin-only cost breakdown response"}

def get_cached_response(user_role):
    # access control applies to cache lookups too
    if user_role != "admin":
        return None
    return response_cache.get("admin")

for role in ["public", "admin"]:
    result = filter_then_rank(chunks, role)
    print(f"Role '{role}' retrieves: {[c['id'] for c in result]}")
    cached = get_cached_response(role)
    print(f"  Cache access: {'allowed' if cached else 'denied'}")
